/**
 * The Scroll
 * ----------
 * Baruch writes Jeremiah's words on a scroll; the king cuts it with a knife and burns it, column by column, and it is written again. Stage: a chamber by the fire, a scribe's reed and ink, a scroll being read aloud, a king's knife shearing it, the fire rising; the book being born again.
 *
 * Palette 0x1a1024 → 0x060402 · light: dawn · hero: scroll
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jeremiah-kit.js.
 */

import { THREE, createScene, column, throne, house, flame, reeds, scroll, person } from './jeremiah-kit.js';

const BG = 0x1a1024;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 1580194081, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x140c1b });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x110a17 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, 14, 0, -17, 1.0 + W.r() * 0.3, { mud: 0x060402 });
    house(W, group, -20, 0, -14, 0.8 + W.r() * 0.3, { mud: 0x060402 });

    /* fire: the burning mark */
    flame(W, group, -11.7, 0, -2.5, 1.1);
    W.point(0xff8a30, 2.0, 55, 0, 3, 0, 0.35);

    /* reeds: a fringe along the near ground */
    reeds(W, group, 25.3, 13.5, 12, 7, { h: 3.6, heads: 0.5 });
    reeds(W, group, 20.6, 11.9, 14, 7, { h: 3.6, heads: 0.5 });
    reeds(W, group, -3.0, 16.5, 11, 7, { h: 3.6, heads: 0.5 });
    reeds(W, group, 11.8, 9.2, 8, 7, { h: 3.6, heads: 0.5 });
    reeds(W, group, -8.9, 11.4, 14, 7, { h: 3.6, heads: 0.5 });

    /* hero: the scroll */
    scroll(W, group, 0, 0.9, 0, 1.2, { ry: 0.5 });
    W.disc([0, 4, -10], 4, 0x22152f, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: -0.31, s: 1.17 });
    person(W, group, [4.5, 0, 6], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.59, s: 1.15 });
    person(W, group, [1, 0, -5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.46, s: 1.03 });

    return W.finish();
}

export default { build };
